#!/usr/bin/env python3
"""
MEDscan all-in-one app: embedded UI + FastAPI model server + shared inference code.

Run:
    pip install fastapi "uvicorn[standard]" python-multipart Pillow torch torchvision
    python medscan_all_in_one.py

Put your trained pneumonia_resnet.pth and fitted temperature.json beside this file.
Research/demo prototype only; not for diagnosis.
"""
from __future__ import annotations

import base64
import json
import os
from io import BytesIO
from pathlib import Path
from typing import Any

import torch
import torch.nn as nn
from fastapi import FastAPI, File, HTTPException, UploadFile
from fastapi.responses import HTMLResponse
from PIL import Image, UnidentifiedImageError
from torchvision import models, transforms
import uvicorn

HERE = Path(__file__).resolve().parent
MODEL_PATH = Path(os.getenv("MEDSCAN_MODEL_PATH", str(HERE / "pneumonia_resnet.pth")))
TEMPERATURE_PATH = Path(os.getenv("MEDSCAN_TEMPERATURE_PATH", str(HERE / "temperature.json")))
DEVICE_SETTING = os.getenv("MEDSCAN_DEVICE")
IMAGE_SIZE = 224
CLASS_NAMES = ["Normal", "Pneumonia"]
HTML_B64 = ""

app = FastAPI(
    title="MEDscan",
    version="1.0.0",
    description="Research/demo chest X-ray classifier. Not for clinical use.",
)
model = None
device = None
temperature = 1.0
load_error: str | None = None


def build_model() -> nn.Module:
    model = models.resnet18(weights=None)
    model.conv1 = nn.Conv2d(1, 64, kernel_size=7, stride=2, padding=3, bias=False)
    model.fc = nn.Linear(model.fc.in_features, 2)
    return model


def preprocess_image(image: Image.Image) -> torch.Tensor:
    # Must match training: grayscale -> 224x224 -> ToTensor -> Normalize([0.5], [0.5]).
    pipeline = transforms.Compose([
        transforms.Grayscale(num_output_channels=1),
        transforms.Resize((IMAGE_SIZE, IMAGE_SIZE)),
        transforms.ToTensor(),
        transforms.Normalize([0.5], [0.5]),
    ])
    return pipeline(image.convert("RGB")).unsqueeze(0)


def extract_state_dict(checkpoint: Any) -> tuple[dict, float | None]:
    found_temperature = None
    if isinstance(checkpoint, dict):
        for key in ("temperature", "calibration_temperature", "T"):
            val = checkpoint.get(key)
            if isinstance(val, (int, float)):
                found_temperature = float(val)
                break
        for key in ("model_state_dict", "state_dict", "model", "weights"):
            if isinstance(checkpoint.get(key), dict):
                checkpoint = checkpoint[key]
                break
    if not isinstance(checkpoint, dict):
        raise ValueError("Unsupported checkpoint format.")
    state_dict = {}
    for key, value in checkpoint.items():
        state_dict[key[7:] if key.startswith("module.") else key] = value
    return state_dict, found_temperature


def read_temperature(checkpoint_temperature: float | None = None) -> float:
    value = checkpoint_temperature
    if TEMPERATURE_PATH.exists():
        data = json.loads(TEMPERATURE_PATH.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            value = data.get("temperature", value)
        elif isinstance(data, (float, int)):
            value = float(data)
    if value is None:
        value = 1.0
    value = float(value)
    if value <= 0:
        raise ValueError("Calibration temperature must be greater than zero.")
    return value


def load_model() -> None:
    global model, device, temperature, load_error
    try:
        device = torch.device(
            DEVICE_SETTING or ("cuda" if torch.cuda.is_available() else "cpu")
        )
        if not MODEL_PATH.exists():
            raise FileNotFoundError(
                f"Missing weights: {MODEL_PATH}. Copy your trained pneumonia_resnet.pth here."
            )
        try:
            checkpoint = torch.load(MODEL_PATH, map_location=device, weights_only=True)
        except TypeError:
            checkpoint = torch.load(MODEL_PATH, map_location=device)
        state_dict, checkpoint_temperature = extract_state_dict(checkpoint)
        candidate = build_model()
        candidate.load_state_dict(state_dict, strict=True)
        candidate.to(device)
        candidate.eval()
        temperature = read_temperature(checkpoint_temperature)
        model = candidate
        load_error = None
    except Exception as exc:
        model = None
        load_error = f"{type(exc).__name__}: {exc}"


def infer(image: Image.Image) -> dict:
    if model is None or device is None:
        raise RuntimeError("Model is not loaded.")
    tensor = preprocess_image(image).to(device)
    with torch.inference_mode():
        logits = model(tensor)
        probs = torch.softmax(logits / temperature, dim=1)[0].detach().cpu()
    idx = int(torch.argmax(probs).item())
    return {
        "prediction": CLASS_NAMES[idx],
        "confidence": float(probs[idx].item()),
        "probabilities": {CLASS_NAMES[i]: float(probs[i].item()) for i in range(2)},
        "temperature": float(temperature),
        "note": "Research/demo output only; not a medical diagnosis.",
    }


@app.on_event("startup")
def startup():
    load_model()


@app.get("/", response_class=HTMLResponse)
def home():
    html = base64.b64decode(HTML_B64).decode("utf-8")
    return HTMLResponse(html)


@app.get("/health")
def health():
    return {
        "status": "ok" if model is not None else "model_unavailable",
        "model_loaded": model is not None,
        "device": str(device) if device is not None else None,
        "temperature": temperature if model is not None else None,
        "error": load_error,
    }


@app.post("/predict")
async def predict(file: UploadFile = File(...)):
    if model is None:
        raise HTTPException(status_code=503, detail=f"Model not loaded: {load_error}")
    content_type = (file.content_type or "").lower()
    if content_type and not (content_type.startswith("image/") or content_type == "application/octet-stream"):
        raise HTTPException(status_code=415, detail="Upload a PNG, JPEG, or other image file.")
    raw = await file.read()
    if not raw:
        raise HTTPException(status_code=400, detail="Uploaded file is empty.")
    if len(raw) > 12 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="Image must be 12 MB or smaller.")
    try:
        image = Image.open(BytesIO(raw))
        image.load()
    except (UnidentifiedImageError, OSError):
        raise HTTPException(status_code=400, detail="File could not be read as an image.")
    try:
        result = infer(image)
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Prediction failed: {type(exc).__name__}: {exc}")
    result["filename"] = file.filename
    return result


if __name__ == "__main__":
    print("MEDscan is starting at http://127.0.0.1:8000")
    print("API docs: http://127.0.0.1:8000/docs | Health: http://127.0.0.1:8000/health")
    uvicorn.run(app, host="127.0.0.1", port=8000)
